    return dict(id=id, panel=panel, line=line, caption=caption, source=source, formula=formula, fmt=fmt, cond=cond, anchor=anchor, seen=seen, fn=fn or FN[panel if panel in FN else panel[0]],
                covers=[('lit', x) for x in lits] + [('call', x) for x in calls] + [('dat', x) for x in dats])
